        total = len(res)
        page = res[offset:offset+limit]
        accounts = []
        for a in page:
            v = a.get("account") or {}
            accounts.append({"pubkey": a.get("pubkey"), "account": {"executable": v.get("executable", False), "lamports": v.get("lamports", 0), "owner": v.get("owner"), "rent_epoch": v.get("rentEpoch")}})
        return jsonify({"program_id": program_id, "total_accounts": total, "limit": limit, "offset": offset, "accounts": accounts})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
